.component-health{display:flex;gap:6px;flex:0 0 auto;margin:7px var(--gutter) 0;flex-wrap:wrap;}
.component-health button{font-size:calc(9px * var(--type-scale));padding:5px 8px;min-height:26px;flex:1;text-align:left;overflow:hidden;text-overflow:ellipsis;}
.component-health .green{color:var(--green);border-color:#286252;}
