.component-health .amber{color:var(--amber);border-color:#695635;}
.component-alert{color:#ffa29a;background:#321c24;border:1px solid #753c40;border-radius:5px;margin:5px var(--gutter) 0;padding:5px 10px;font-size:calc(10px * var(--type-scale));flex:0 0 auto;max-height:48px;overflow:auto;}
